\label{prop:Vn}
Assume \ref{A:mart}--\ref{A:attractor}. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$ and all $h\in\cont{3}{\Theta}$:
\begin{align*}
    \abs{\esp{h(\theta_n) - h(\phi_{n\alpha}(\theta_0))} - \alpha V^{(\alpha)}_{n}} \le C\alpha^2,
\end{align*}
where the quantity $V^{(\alpha)}_{n}$ is given by:
\begin{align*}
    V^{(\alpha)}_{n} := \sum_{k=0}^{n-1} &\mathbb{E}\Big[D(h\circ\varphi_{n-(k+1)})(\theta_{k})(f(\theta_{k},X_{k})-\bar{f}(X_{k}))\\
    &\quad - D^2(h\circ\varphi_{n-(k+1)})(\theta_{k}) \left((f (\theta_{k},X_{k})-\bar{f}(X_{k}))^{\otimes 2} + Q(\theta_{k},X_{k})\right)\Big].
\end{align*}

Moreover, $V^{(\alpha)}_n$ is bounded independently of $\alpha$ and $n$.

\begin{align*}
        \abs{\esp{h(\theta_n) - h(\phi_{n\alpha}(\theta_0))} - \alpha V^{(\alpha)}_{n}} \le C\alpha^2,
    \end{align*}

\begin{align*}
        V^{(\alpha)}_{n} := \sum_{k=0}^{n-1} &\mathbb{E}\Big[D(h\circ\varphi_{n-(k+1)})(\theta_{k})(f(\theta_{k},X_{k})-\bar{f}(X_{k}))\\
        &\quad - D^2(h\circ\varphi_{n-(k+1)})(\theta_{k}) \left((f (\theta_{k},X_{k})-\bar{f}(X_{k}))^{\otimes 2} + Q(\theta_{k},X_{k})\right)\Big].
    \end{align*}

Following the definition of the stochastic and deterministic recurrences, the difference $z_{n, k} - z_{n, k+1}$ that appears in \eqref{eq:z_diff} is equal to 
\begin{align}
    z_{n, k+1} - z_{n, k}  &= \esp{h(\varphi_{n-k}(\theta_{k})) - h(\varphi_{n-(k+1)}(\theta_{k+1}))}\nonumber\\
    &= \mathbb{E}\big[h\circ\varphi_{n-(k+1)}(\theta_{k} + \alpha \bar{f}(\theta_{k}))\nonumber\\
    &\qquad - h\circ\varphi_{n-(k+1)}(\theta_{k} + \alpha (f(\theta_{k},X_{k})+M_{k+1}))\big] \label{eq:before_taylor}
\end{align}
If $g:\mathbb{R}^d\to\mathbb{R}$ is a thrice differentiable function whose third derivative is bounded by $\norm{D^3g}$, by using a Taylor expansion, we have that $g(x+a) - g(x+ b) = Dg(x) (a-b) + D^2g(x) (a-b)^{\otimes2} + R$, where $R$ is a remainder term that is smaller than $\frac{c}{6}\norm{a-b}^3$. In our proof, we use this Taylor expansion with the function $g=h\circ\varphi_{n-(k+1)}$, $x=\theta_{k}$, $a=\alpha(f(\theta_{k},X_{k})+M_{k+1})$ and $b=\alpha\bar{f}(\theta_{k})$. Applying this to \eqref{eq:before_taylor} shows that 
\begin{align}
    z_{n, k+1} - z_{n, k} = \alpha A_{n,k} + \frac{\alpha^2}{2} B_{n,k} + R_{n,k},
\end{align}
where $A_{n,k}$ and $B_{n,k}$ are equal to 
\begin{align*}

    A_{n,k} &:= \esp{D(h\circ\varphi_{n-(k+1)})(\theta_{k})(f(\theta_{k},X_{k})+M_{k+1}-\bar{f}(X_{k}))}\\
    B_{n,k} &:= \esp{D^2(h\circ\varphi_{n-(k+1)})(\theta_{k}) (f (\theta_{k},X_{k})+M_{k+1}-\bar{f}(X_{k}))^{\otimes 2}},
\end{align*}
and $R_{n,k}$ is a remainder term.

By assumption \ref{A:mart}, the conditional expectation and variance of the martingale term are equal to $\esp{M_{k+1}\mid \mathcal{F}_{k}} = 0$ and $\esp{M_{k+1}^{\otimes2}\mid \mathcal{F}_{k}}=Q(\theta_{k},X_{k})$. By using the total law of expectation, this shows that $A_{n,k}$ and $B_{n,k}$ can be simplified as:
\begin{align*}
    A_{n,k} &:= \esp{D(h\circ\varphi_{n-(k+1)})(\theta_{k})(f(\theta_{k},X_{k})-\bar{f}(X_{k}))}\\
    B_{n,k} &:= \esp{D^2(h\circ\varphi_{n-(k+1)})(\theta_{k}) \left((f (\theta_{k},X_{k})-\bar{f}(X_{k}))^{\otimes 2} + Q(\theta_{k},X_{k})\right)}.
\end{align*}
By definition, $V^{(\alpha)}_n = \sum_{k=0}^{n-1}(A_{n,k} + \alpha B_{n,k}/2)$. Hence, combining this with \eqref{eq:z_diff} shows that
\begin{align*}
    \esp{h(\theta_n) - h(\phi_{n\alpha}(\theta_0))} &= V^{(\alpha)}_n + \sum_{k=0}^{n-1} R_{n,k}.
\end{align*}
To complete the proof, it remains to be shown that there exists a constant such that $\sum_{k=0}^{n-1} R_{n,k} \le C\alpha^2$ and that $V^{(\alpha)}_n$ is bounded independently of $\alpha$ and $n$. There are three terms, corresponding to $R$, $B$, and $\sum_{k=1}^n A_{n,k}$:\\
\textbf{Case of $R$}. In Lemma~\ref{lemma:exponentially_small_derivatives}, we show that the norm of the derivatives of $h\circ\varphi_{n-k}$ are smaller than $c_1 e^{- c_2\alpha (n-k)}$. As the derivatives of $h$ are bounded by $1$, this implies there exists $c$ independent of $\alpha$ and $n$ such that $\norm{D^3(h\circ\varphi_{n-k})}\le ce^{-c_2\alpha (n-k)}$. Hence, there exists $c'>0$ such that: 
\begin{align*}
    \sum_{k=0}^{n-1} \norm{R_{n,k}}\le c' \alpha^3 \sum_{k=0}^{n-1} e^{-c_2\alpha (n-k)} \le c' \alpha^3 \sum_{k=0}^\infty e^{-c_2\alpha k} \le c'c_3 \alpha^2.
\end{align*}

\textbf{Case of $B$}.     The proof that $\sum_{k=1}^n \alpha B_{n,k}$ is bounded independently of $n$ and $\alpha$ is similar since the factor $\alpha$ cancels out with the factor $1/\alpha$ that comes out of $\sum_{k=0}^\infty e^{-c_2\alpha k}$.

\textbf{Case of $A$} Showing that $\sum_{k=1}^n A_{n,k}$ is bounded independently of $n$ and $\alpha$ is more subtle and uses the fact that $\bar{f}$ is the ``averaged'' version of $f$ with respect to the transition kernel $K$.  The proof of this is a consequence of the first point of Lemma~\ref{lem:Poisson} that is stated in Section~\ref{sec:proof_lemma}.

