\begin{align*}
        \esp{h(\theta_n) - h(\phi_{n\alpha}(\theta_0))} &= V^{(\alpha)}_n + \sum_{k=0}^{n-1} R_{n,k}.
    \end{align*}

\begin{align*}
        \sum_{k=0}^{n-1} \norm{R_{n,k}}\le c' \alpha^3 \sum_{k=0}^{n-1} e^{-c_2\alpha (n-k)} \le c' \alpha^3 \sum_{k=0}^\infty e^{-c_2\alpha k} \le c'c_3 \alpha^2.
